// Applies YAGNI: solve today's case, keep the seam obvious.
class PaymentService {
    private final CardGateway gateway;
    PaymentService(CardGateway gateway) { this.gateway = gateway; }

    void charge(Order order) {
        if (!order.isPayable()) throw new IllegalStateException("not payable");
        gateway.charge(order.id(), order.amount());
    }
}
